def removeOnes(grid):
    # m, n: grid size
    m = len(grid)
    n = len(grid[0])

    # Precompute cell-to-index in state bitmask
    def idx(i, j):
        return i * n + j

    # Encode the grid as a state bitmask (int)
    def encode(grid):
        state = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    state |= 1 << idx(i, j)
        return state

    from functools import lru_cache

    @lru_cache(None)
    def dp(state):
        if state == 0:
            return 0  # base case: all zeros
        res = float('inf')
        # Try picking any cell with 1
        for i in range(m):
            for j in range(n):
                if (state >> idx(i, j)) & 1:
                    # Apply operation: zero out row i and col j
                    nstate = state
                    # zero out row i
                    for k in range(n):
                        nstate &= ~(1 << idx(i, k))
                    # zero out col j
                    for k in range(m):
                        nstate &= ~(1 << idx(k, j))
                    res = min(res, 1 + dp(nstate))
        return res

    return dp(encode(grid))
